    const handleUploadPdf = async (opts?: { skipHomologConfirm?: boolean }) => {
        if (enviandoAnexoRef.current) return
        const file = fileInputRef.current?.files?.[0] ?? pendingUploadFileRef.current
        if (!file || !id) {
            toast.warning('Selecione um arquivo PDF ou CSV')
            return
        }
        if (!isValidFaturaFile(file)) {
            toast.error('Formato inválido. Envie PDF ou CSV.')
            return
        }
        pendingUploadFileRef.current = file

        if (!opts?.skipHomologConfirm) {
            const cartaoLookup = cartoesLookup.find((c) => Number(c.id) === Number(fatura?.cartao_id))
            const homologacao = resolveCartaoHomologacao({
                nome: fatura?.cartao_nome ?? cartaoLookup?.nome,
                banco: cartaoLookup?.banco,
                importacao_pdf_homologada: fatura?.importacao_pdf_homologada ?? cartaoLookup?.importacao_pdf_homologada,
                parser_homologado: fatura?.parser_homologado ?? cartaoLookup?.parser_homologado,
            }, parsersHomologados)
            const attemptKey = `${fatura?.cartao_id ?? ''}|${file.name}:${file.size}:${file.lastModified}`
            if (precisaAvisarParserNaoHomologado({
                temArquivo: true,
                cartaoId: fatura?.cartao_id,
                cartaoIdentificado: Boolean(fatura?.cartao_nome || cartaoLookup),
                homologada: homologacao.homologada,
                jaConfirmou: homologConfirmRef.current === attemptKey,
            })) {
                setHomologModalOpen(true)
                return
            }
        }

        if (!iniciarEnvioAnexo()) return
        try {
            const result = await faturasService.uploadPdf({
                id: Number(id),
                arquivo_pdf: file,
                processar_automatico: processarAuto,
                ...competenciaDaFaturaAberta(),
            })
            await handleUploadSuccess(result)
        } catch (error) {
            if (abrirCadastroSeArquivoDiverge(error)) return
            if (avisarFaturaProcessando(error)) return
            if (error instanceof FaturaTitularError) {
                setTitularTitulares(error.titulares)
                setTitularNomeNoCartao(error.nome_no_cartao ?? null)
                setTitularPessoas(error.pessoas)
                setTitularSugestao(error.sugestao)
                setTitularOrientacao(error.orientacao ?? error.message ?? null)
                setTitularModalOpen(true)
                return
            }
            if (error instanceof FaturaAnexoDuplicadoError) {
                setAnexoDuplicadoError(error)
                setAnexoDuplicadoModalOpen(true)
                return
            }
            if (error instanceof FaturaJaAnexadaError) {
                setJaAnexadaError(error)
                setJaAnexadaModalOpen(true)
                return
            }
            if (error instanceof FaturaSelecaoError) {
                openSelecaoModal(error)
                return
            }
            if (error instanceof PdfSenhaError) {
                openSenhaModal(error.senha_pdf ?? null, { viaUpload: true })
                return
            }
            toast.error((error as Error)?.message || 'Erro ao enviar arquivo')
        } finally {
            encerrarEnvioAnexo()
        }
    }

