    const saveTransacao = async (
        tx: TransacoesList,
        patch: Partial<Pick<
            TransacoesList,
            | 'categoria_id'
            | 'categoria_nome'
            | 'categoria_cor'
            | 'subcategoria_id'
            | 'subcategoria_nome'
            | 'subcategoria_cor'
            | 'responsavel_id'
            | 'valor'
            | 'observacoes'
            | 'origem_compra'
            | 'eh_assinatura'
            | 'plataforma_id'
            | 'plataforma_nome'
            | 'plataforma_cor'
        >> & {
            propagar_grupo?: boolean
        }
    ) => {
        if (!tx.id) return
        setSavingIds((prev) => ({ ...prev, [tx.id!]: true }))
        try {
            const valor = patch.valor !== undefined ? patch.valor : tx.valor
            const categoriaId = patch.categoria_id !== undefined ? patch.categoria_id : (tx.categoria_id ?? null)
            const subcategoriaId = patch.subcategoria_id !== undefined
                ? patch.subcategoria_id
                : (categoriaId ? (tx.subcategoria_id ?? null) : null)
            const origemCompra = patch.origem_compra !== undefined
                ? patch.origem_compra
                : (tx.origem_compra ?? null)
            const plataformaId = patch.plataforma_id !== undefined
                ? patch.plataforma_id
                : (tx.plataforma_id ?? null)
            const ehAssinatura = patch.eh_assinatura !== undefined
                ? patch.eh_assinatura
                : (tx.eh_assinatura ?? null)
            const { propagar_grupo: propagarGrupo, ...rowPatch } = patch
            const payload: TransacoesModel = {
                id: tx.id,
                transacao_id: tx.id,
                cartao_id: tx.cartao_id ?? null,
                fatura_id: tx.fatura_id ?? Number(id),
                estabelecimento_id: tx.estabelecimento_id ?? null,
                estabelecimento: tx.estabelecimento_id ? undefined : (tx.estabelecimento ?? null),
                valor: valor ?? null,
                valor_parcela: valor ?? null,
                data: tx.data ?? null,
                tipo: tx.tipo ?? null,
                origem_compra: origemCompra,
                eh_assinatura: ehAssinatura != null ? Boolean(ehAssinatura) : undefined,
                categoria_id: categoriaId,
                subcategoria_id: subcategoriaId,
                plataforma_id: plataformaId,
                responsavel_id: patch.responsavel_id !== undefined ? patch.responsavel_id : (tx.responsavel_id ?? null),
                observacoes: patch.observacoes !== undefined ? patch.observacoes : (tx.observacoes ?? null),
                propagar_grupo: propagarGrupo || undefined,
            }

            const resposta = await transacoesService.editTransacoes(payload)
            const gravouClassificacao = patch.categoria_id !== undefined || patch.subcategoria_id !== undefined
            const temCategoria = categoriaId != null && Number(categoriaId) > 0
            const pergunta = gravouClassificacao && temCategoria
                ? parseAplicarSubcategoria(resposta)
                : null
            const ehAssinaturaResposta = gravouClassificacao ? ehAssinaturaDaResposta(resposta) : null
            if (pergunta) {
                setAplicarSubcategoria({ pergunta, payload })
            }
            setTransacoes((prev) =>
                prev.map((item) => {
                    const sameGrupo = Boolean(
                        propagarGrupo
                        && tx.compra_grupo_id
                        && item.compra_grupo_id === tx.compra_grupo_id
                    )
                    const recebeGrupo = Boolean(
                        gravouClassificacao
                        && temCategoria
                        && !sameGrupo
                        && parcelaDoGrupoRecebeClassificacao(
                            item,
                            tx,
                            { categoria_id: categoriaId, subcategoria_id: subcategoriaId },
                        )
                    )
                    if (item.id !== tx.id && !sameGrupo && !recebeGrupo) return item
                    const next = recebeGrupo
                        ? {
                            ...item,
                            categoria_id: categoriaId,
                            subcategoria_id: subcategoriaId,
                        }
                        : { ...item, ...rowPatch }
                    if (item.id === tx.id && ehAssinaturaResposta !== null) {
                        next.eh_assinatura = ehAssinaturaResposta
                    }
                    if (recebeGrupo || rowPatch.categoria_id !== undefined) {
                        const categoriaAlvo = recebeGrupo ? categoriaId : rowPatch.categoria_id
                        const categoria = categoriasLookup.find((o) => Number(o.id) === Number(categoriaAlvo))
                        next.categoria_nome = rowPatch.categoria_nome ?? categoria?.nome
                        next.categoria_cor = rowPatch.categoria_cor ?? categoria?.cor
                        if (
                            !recebeGrupo
                            && rowPatch.subcategoria_id === undefined
                            && rowPatch.categoria_id !== item.categoria_id
                        ) {
                            next.subcategoria_id = null
                            next.subcategoria_nome = undefined
                            next.subcategoria_cor = undefined
                        }
                    }
                    if (recebeGrupo || rowPatch.subcategoria_id !== undefined) {
                        const subAlvo = recebeGrupo ? subcategoriaId : rowPatch.subcategoria_id
                        const opts = categoriaId ? (subcategoriasByCategoria[categoriaId] ?? []) : []
                        const opt = opts.find((o) => Number(o.value) === Number(subAlvo))
                        next.subcategoria_nome = rowPatch.subcategoria_nome ?? opt?.label
                        next.subcategoria_cor = subAlvo
                            ? (rowPatch.subcategoria_cor ?? opt?.cor ?? null)
                            : null
                    }
                    if (!recebeGrupo && rowPatch.origem_compra !== undefined) {
                        next.origem_compra_label =
                            origensCompraOptions.find((o) => o.value === rowPatch.origem_compra)?.label
                            ?? origemCompraLabel[rowPatch.origem_compra ?? '']
                            ?? null
                    }
                    if (!recebeGrupo && rowPatch.plataforma_id !== undefined) {
                        const plataforma = plataformasLookup.find((o) => o.id === rowPatch.plataforma_id)
                        next.plataforma_nome = rowPatch.plataforma_nome ?? plataforma?.nome
                        next.plataforma_cor = rowPatch.plataforma_cor ?? plataforma?.cor
                    }
                    if (!recebeGrupo && rowPatch.responsavel_id !== undefined) {
                        const responsavel =
                            responsaveisLookup.find((r) => Number(r.id) === Number(rowPatch.responsavel_id))
                            ?? null
                        const fromOptions = responsaveisOptions.find((o) => Number(o.value) === rowPatch.responsavel_id)
                        next.responsavel_nome = responsavel?.nome ?? fromOptions?.label
                        next.responsavel_tipo = responsavel?.tipo ?? next.responsavel_tipo
                    }
                    return next
                })
            )
            if (patch.valor !== undefined && tx.id) {
                setValorDrafts((prev) => ({
                    ...prev,
                    [tx.id!]: Number(patch.valor).toFixed(2),
                }))
            }
            if (patch.observacoes !== undefined && tx.id) {
                setObservacaoDrafts((prev) => ({
                    ...prev,
                    [tx.id!]: patch.observacoes ?? '',
                }))
            }
        } catch (error) {
            toast.error('Erro ao atualizar transação')
            await loadTransacoes(id!)
        } finally {
            setSavingIds((prev) => {
                const next = { ...prev }
                delete next[tx.id!]
                return next
            })
        }
    }

